import React, { useEffect, useMemo, useState } from "react";
import { Avatar, Button, Drawer, Grid, Layout, Menu, Space, Tag, Typography } from "antd";
import {
  ControlOutlined,
  LoginOutlined,
  LogoutOutlined,
  MenuFoldOutlined,
  MenuOutlined,
  MenuUnfoldOutlined,
  PlayCircleOutlined,
  SettingOutlined,
  UserOutlined
} from "@ant-design/icons";
import { NavLink, Outlet, useLocation, useNavigate } from "react-router-dom";
import { getConfig } from "../config/api";
import { useAuth } from "../contexts/AuthContext";
import { appColors } from "../theme/colors";

const { Header, Content, Footer, Sider } = Layout;
const { Text, Title } = Typography;
const { useBreakpoint } = Grid;
const APP_VERSION = "v1.0.0";

function MainLayout() {
  const screens = useBreakpoint();
  const isMobile = !screens.lg;
  const [collapsed, setCollapsed] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const { currentUser, logout } = useAuth();
  const config = getConfig();

  const menuItems = useMemo(() => {
    const items = [
      {
        key: "/transport-orders",
        icon: <PlayCircleOutlined />,
        label: <NavLink to="/transport-orders">Tạo lệnh</NavLink>
      },
      {
        key: "/process-priority",
        icon: <ControlOutlined />,
        label: <NavLink to="/process-priority">Cấu hình ưu tiên</NavLink>
      }
    ];

    if (currentUser?.role === "Admin") {
      items.push({
        key: "/user-settings",
        icon: <SettingOutlined />,
        label: <NavLink to="/user-settings">Cài đặt người dùng</NavLink>
      });
    }

    return items;
  }, [currentUser?.role]);

  const selectedKey = useMemo(() => {
    if (location.pathname.startsWith("/transport-orders")) {
      return "/transport-orders";
    }
    if (location.pathname.startsWith("/process-priority")) {
      return "/process-priority";
    }
    if (location.pathname.startsWith("/user-settings")) {
      return "/user-settings";
    }
    return location.pathname;
  }, [location.pathname]);

  const activePage = useMemo(() => {
    const pageMap = {
      "/transport-orders": {
        title: "Tạo lệnh",
        subtitle: "Chọn line, chọn quy trình và theo dõi danh sách lệnh đang chờ hoặc đang chạy"
      },
      "/process-priority": {
        title: "Process Priority",
        subtitle: "Cấu hình mức độ ưu tiên của quy trình theo từng Line sản xuất"
      },
      "/user-settings": {
        title: "Cài đặt người dùng",
        subtitle: "Quản lý danh sách tài khoản, quyền truy cập và lịch sử cập nhật"
      }
    };

    return pageMap[selectedKey] || {
      title: config.APP_NAME,
      subtitle: "STI AGV System Configuration"
    };
  }, [config.APP_NAME, selectedKey]);

  useEffect(() => {
    if (isMobile) {
      setMobileMenuOpen(false);
    }
  }, [isMobile, selectedKey]);

  const handleToggleNav = () => {
    if (isMobile) {
      setMobileMenuOpen(true);
      return;
    }
    setCollapsed((value) => !value);
  };

  const handleLogout = () => {
    logout(true);
    navigate("/login");
  };

  const navigation = (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", background: "#ffffff" }}>
      {/* Brand logo container */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: collapsed && !isMobile ? "center" : "flex-start",
          gap: 12,
          padding: collapsed && !isMobile ? "20px 12px" : "20px 24px",
          borderBottom: "1px solid #f1f5f9"
        }}
      >
        <img
          src="/Logo.png"
          alt="Logo"
          style={{
            width: collapsed && !isMobile ? 36 : 42,
            height: collapsed && !isMobile ? 36 : 42,
            objectFit: "contain"
          }}
        />
        {collapsed && !isMobile ? null : (
          <div style={{ minWidth: 0 }}>
            <Title level={4} style={{ margin: 0, fontSize: 15, fontWeight: 800, letterSpacing: "-0.3px", color: "#0f172a" }}>
              AGV Configuration
            </Title>
          </div>
        )}
      </div>

      <div style={{ flex: 1, padding: "16px 12px" }}>
        <Menu
          className="app-sidebar-menu"
          mode="inline"
          selectedKeys={[selectedKey]}
          items={menuItems}
          style={{ borderInlineEnd: 0, background: "transparent" }}
        />
      </div>

      <div
        style={{
          padding: collapsed && !isMobile ? "12px 8px 18px" : "12px 24px 18px",
          borderTop: "1px solid #f1f5f9",
          textAlign: "center",
          flexShrink: 0
        }}
      >
        <Text style={{ color: "#94a3b8", fontSize: 12, fontWeight: 400 }}>
          {APP_VERSION}
        </Text>
      </div>
    </div>
  );

  const userPanel = currentUser ? (
    <Space size={16} align="center">
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end",
          lineHeight: 1.2
        }}
      >
        <Text strong style={{ fontSize: 13.5, color: "#0f172a", whiteSpace: "nowrap" }}>
          {currentUser.fullName}
        </Text>
        <Tag
          color="geekblue"
          bordered={false}
          style={{
            fontSize: 10,
            marginInlineEnd: 0,
            fontWeight: 600,
            padding: "0 6px",
            marginTop: 4
          }}
        >
          {currentUser.role.toUpperCase()}
        </Tag>
      </div>

      <Avatar
        size={36}
        icon={<UserOutlined />}
        style={{
          background: appColors.primarySoft,
          color: appColors.primary,
          border: `1px solid ${appColors.primaryBorder}`
        }}
      />

      <Button
        type="text"
        icon={<LogoutOutlined style={{ color: "#ef4444" }} />}
        onClick={handleLogout}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: 36,
          height: 36,
          borderRadius: "50%",
          background: "#fef2f2",
          border: "none"
        }}
        title="Đăng xuất"
      />
    </Space>
  ) : (
    <Button
      type="primary"
      icon={<LoginOutlined />}
      onClick={() => navigate("/login")}
      style={{
        borderRadius: 10,
        background: `linear-gradient(135deg, ${appColors.primary}, ${appColors.primaryGradientEnd})`,
        border: "none"
      }}
    >
      Đăng nhập
    </Button>
  );

  return (
    <Layout style={{ height: "100vh", overflow: "hidden", background: "#f8fafc" }}>
      {isMobile ? (
        <Drawer
          placement="left"
          open={mobileMenuOpen}
          onClose={() => setMobileMenuOpen(false)}
          closable={false}
          width={260}
          styles={{ body: { padding: 0 }, content: { background: "#fff" } }}
        >
          {navigation}
        </Drawer>
      ) : (
        <Sider
          trigger={null}
          collapsible
          collapsed={collapsed}
          width={240}
          collapsedWidth={80}
          style={{
            background: "#fff",
            borderRight: "1px solid #f1f5f9",
            height: "100vh",
            transition: "all 0.2s ease"
          }}
        >
          {navigation}
        </Sider>
      )}

      <Layout style={{ display: "flex", flexDirection: "column", height: "100vh", overflow: "hidden" }}>
        <Header
          style={{
            background: "#fff",
            borderBottom: "1px solid #f1f5f9",
            padding: isMobile ? "0 16px" : "0 24px",
            height: 64,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 16,
            flexShrink: 0,
            width: "100%"
          }}
        >
          <Space size={16} style={{ minWidth: 0 }}>
            <Button
              type="text"
              icon={
                isMobile
                  ? <MenuOutlined />
                  : collapsed
                    ? <MenuUnfoldOutlined />
                    : <MenuFoldOutlined />
              }
              onClick={handleToggleNav}
              style={{
                width: 36,
                height: 36,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                background: "#f8fafc",
                borderRadius: "8px"
              }}
              aria-label="Toggle navigation"
            />

            <div style={{ display: "flex", flexDirection: "column", lineHeight: 1.2, minWidth: 0 }}>
              <Text strong style={{ fontSize: 15, color: "#0f172a", fontWeight: 700 }}>
                {activePage.title}
              </Text>
              {!isMobile && (
                <Text type="secondary" style={{ fontSize: 11.5, color: "#64748b", marginTop: 1 }}>
                  {activePage.subtitle}
                </Text>
              )}
            </div>
          </Space>

          <div style={{ marginLeft: "auto" }}>
            {userPanel}
          </div>
        </Header>

        <Content style={{ padding: isMobile ? "12px 12px 0px 12px" : "20px 20px 0px 20px", flex: 1, overflow: "hidden", display: "flex", flexDirection: "column", minHeight: 0, transition: "padding 0.2s" }}>
          <div style={{ width: "100%", flex: 1, display: "flex", flexDirection: "column", overflow: "hidden", minHeight: 0 }}>
            <Outlet />
          </div>
        </Content>

        <Footer style={{ textAlign: "center", color: "#94a3b8", background: "transparent", padding: "4px 24px 8px", fontSize: 11.5, flexShrink: 0 }}>
          AGV Configuration | Designed by STI.AI &copy; 2026
        </Footer>
      </Layout>
    </Layout>
  );
}

export default MainLayout;
